'use client';
import { useState } from 'react'; import { Plus, Trash2 } from 'lucide-react'; import { API } from '@/lib/api';
export default function BannerManager({ initial }: { initial: any[] }) { const [items,setItems]=useState(initial); const create=async(e:React.FormEvent<HTMLFormElement>)=>{e.preventDefault();const form=e.currentTarget;const raw=Object.fromEntries(new FormData(form));const r=await fetch(`${API}/banners`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...raw,position:Number(raw.position),active:true})});if(r.ok){const saved=await r.json();setItems(x=>[...x,saved]);form.reset();}}; const remove=async(id:string)=>{if(!confirm('Delete banner?'))return;const r=await fetch(`${API}/banners/${id}`,{method:'DELETE'});if(r.ok)setItems(x=>x.filter(b=>b.id!==id));}; return <div className="grid gap-5 xl:grid-cols-[1fr_360px]"><div className="grid gap-4 sm:grid-cols-2">{items.map(b=><article className="card overflow-hidden" key={b.id}><div className="aspect-[16/7] bg-[#eee]"><img src={b.image} alt="" className="h-full w-full object-cover" /></div><div className="flex items-start justify-between p-5"><div><h2 className="font-black">{b.title}</h2><p className="mt-1 text-xs text-muted">{b.subtitle}</p></div><button onClick={()=>remove(b.id)} className="text-red-600"><Trash2 size={16}/></button></div></article>)}</div><form onSubmit={create} className="card h-fit space-y-4 p-6"><h2 className="text-lg font-black"><Plus className="mr-2 inline" size={17}/>New banner</h2>{['title','subtitle','image','link','position'].map(name=><label key={name}><span className="mb-2 block text-[10px] font-bold uppercase text-muted">{name}</span><input required={['title','image'].includes(name)} name={name} type={name==='position'?'number':'text'} className="input" placeholder={name==='image'?'/images/banner.jpg':''}/></label>)}<button className="w-full rounded-lg bg-ink py-3 text-xs font-bold text-white">Add banner</button></form></div>; }
